// src/components/KnowYourCandidate.js (Enhanced with Gemini AI)
import React, { useState } from 'react';

const KnowYourCandidate = ({ user, language }) => {
  const [candidateInfo, setCandidateInfo] = useState(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');

  // Gemini AI API integration
  const fetchCandidateInfo = async () => {
    if (!user?.constituency) {
      setError(language === 'hindi' 
        ? 'कृपया पहले अपना निर्वाचन क्षेत्र सेट करें' 
        : 'Please set your constituency first'
      );
      return;
    }

    setLoading(true);
    setError('');

    try {
      // Gemini AI API call
      const response = await fetch(`https://generativelanguage.googleapis.com/v1beta/models/gemini-pro:generateContent?key=YOUR_GEMINI_API_KEY`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          contents: [{
            parts: [{
              text: `Provide detailed information about current election candidates for ${user.constituency} constituency in India. Include their names, parties, education background, key promises, and political experience. Format the response as JSON with this structure: {
                "candidates": [
                  {
                    "name": "Candidate Name",
                    "party": "Party Name", 
                    "education": "Educational Background",
                    "experience": "Political Experience",
                    "promises": ["Promise 1", "Promise 2", "Promise 3"],
                    "contact": "Contact Information"
                  }
                ]
              }`
            }]
          }]
        })
      });

      const data = await response.json();
      
      if (data.candidates) {
        setCandidateInfo(data.candidates);
      } else {
        // Fallback dummy data agar API fail ho
        setCandidateInfo(getDummyCandidates(user.constituency));
      }
    } catch (error) {
      console.error('Gemini AI Error:', error);
      // Fallback to dummy data
      setCandidateInfo(getDummyCandidates(user.constituency));
      setError(language === 'hindi' 
        ? 'लाइव डेटा लोड नहीं हो सका, सैंपल डेटा दिखाया जा रहा है' 
        : 'Could not load live data, showing sample data'
      );
    } finally {
      setLoading(false);
    }
  };

  // Dummy data as fallback
  const getDummyCandidates = (constituency) => {
    const candidatesData = {
      'Delhi': [
        {
          name: 'अरविंद केजरीवाल / Arvind Kejriwal',
          party: 'आम आदमी पार्टी / Aam Aadmi Party',
          education: 'आईआईटी खड़गपुर (बी.टेक) / IIT Kharagpur (B.Tech)',
          experience: 'मुख्यमंत्री दिल्ली (2015-वर्तमान) / Chief Minister Delhi (2015-Present)',
          promises: [
            '24x7 बिजली और पानी की आपूर्ति / 24x7 Electricity and Water Supply',
            'शिक्षा और स्वास्थ्य में सुधार / Improve Education and Healthcare',
            'महिला सुरक्षा को प्राथमिकता / Priority to Women Safety'
          ],
          contact: 'aapdelhi@example.com'
        },
        {
          name: 'मीनाक्षी लेखी / Meenakshi Lekhi',
          party: 'भारतीय जनता पार्टी / BJP',
          education: 'दिल्ली विश्वविद्यालय (एलएलबी) / Delhi University (LLB)',
          experience: 'सांसद और केंद्रीय मंत्री / MP and Central Minister',
          promises: [
            'रोजगार सृजन कार्यक्रम / Job Creation Programs',
            'बुनियादी ढांचा विकास / Infrastructure Development', 
            'युवाओं के लिए कौशल विकास / Skill Development for Youth'
          ],
          contact: 'bjpdelhi@example.com'
        }
      ],
      'Mumbai North': [
        {
          name: 'गोपाल शेट्टी / Gopal Shetty',
          party: 'भारतीय जनता पार्टी / BJP',
          education: 'मुंबई विश्वविद्यालय / Mumbai University',
          experience: 'सांसद मुंबई उत्तर / MP Mumbai North',
          promises: [
            'लोकल ट्रेन सुविधाओं में सुधार / Improve Local Train Facilities',
            'मुंबई की बाढ़ समस्या का समाधान / Solve Mumbai Flooding Issues',
            'आवास योजनाओं का विस्तार / Expand Housing Schemes'
          ],
          contact: 'bjpmumbai@example.com'
        }
      ]
    };

    return candidatesData[constituency] || [
      {
        name: language === 'hindi' ? 'उम्मीदवार जानकारी उपलब्ध नहीं' : 'Candidate info not available',
        party: '-',
        education: '-',
        experience: '-',
        promises: [language === 'hindi' ? 'जानकारी अपडेट की जा रही है' : 'Information being updated'],
        contact: '-'
      }
    ];
  };

  const translations = {
    hindi: {
      title: "अपने उम्मीदवार को जानें",
      constituency: "आपका निर्वाचन क्षेत्र",
      fetchButton: "उम्मीदवार जानकारी प्राप्त करें",
      loading: "जानकारी लोड हो रही है...",
      candidateInfo: "उम्मीदवार की जानकारी",
      name: "नाम",
      party: "पार्टी",
      education: "शिक्षा",
      experience: "राजनीतिक अनुभव",
      promises: "वादे",
      contact: "संपर्क",
      noConstituency: "कृपया पहले अपना निर्वाचन क्षेत्र सेट करें"
    },
    english: {
      title: "Know Your Candidate",
      constituency: "Your Constituency",
      fetchButton: "Get Candidate Info",
      loading: "Loading information...",
      candidateInfo: "Candidate Information",
      name: "Name",
      party: "Party",
      education: "Education",
      experience: "Political Experience",
      promises: "Promises",
      contact: "Contact",
      noConstituency: "Please set your constituency first"
    }
  };

  const t = translations[language];

  return (
    <div className="know-your-candidate">
      <h2>{t.title}</h2>
      
      {user?.constituency ? (
        <div className="constituency-info">
          <p><strong>{t.constituency}:</strong> {user.constituency}</p>
        </div>
      ) : (
        <div className="warning-message">
          <p>{t.noConstituency}</p>
        </div>
      )}

      <button 
        onClick={fetchCandidateInfo} 
        className="fetch-button"
        disabled={loading || !user?.constituency}
      >
        {loading ? t.loading : t.fetchButton}
      </button>

      {error && <div className="error-message">{error}</div>}

      {candidateInfo && (
        <div className="candidates-list">
          <h3>{t.candidateInfo}</h3>
          {candidateInfo.map((candidate, index) => (
            <div key={index} className="candidate-card">
              <div className="candidate-header">
                <h4>{candidate.name}</h4>
                <span className="party-badge">{candidate.party}</span>
              </div>
              
              <div className="candidate-details">
                <p><strong>{t.education}:</strong> {candidate.education}</p>
                <p><strong>{t.experience}:</strong> {candidate.experience}</p>
                <p><strong>{t.contact}:</strong> {candidate.contact}</p>
              </div>

              <div className="promises-section">
                <strong>{t.promises}:</strong>
                <ul>
                  {candidate.promises.map((promise, promiseIndex) => (
                    <li key={promiseIndex}>{promise}</li>
                  ))}
                </ul>
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
};

export default KnowYourCandidate;
